"""Parse teich/pi agent-trace JSONL files into normalized OpenAI-style messages.

Trace format (one JSON object per line):

    {"type": "session", "version": 3, "id": ..., "cwd": ...}
    {"type": "model_change" | "thinking_level_change", ...}
    {"type": "message", "message": {"role": ..., "content": [<blocks>]}}

Roles seen in the traces: ``developer`` (system prompt), ``user``,
``assistant``, ``toolResult``. Assistant content blocks are
``{"type": "thinking" | "text" | "toolCall", ...}``; toolCall blocks carry
``id``, ``name`` and ``arguments`` (a JSON object).

Normalized output messages:

    {"role": "system" | "user", "content": str}
    {"role": "assistant", "content": str,
     "reasoning_content": str (optional),
     "tool_calls": [{"id", "type": "function",
                     "function": {"name", "arguments": <json str>}}] (optional)}
    {"role": "tool", "content": str}
"""

from __future__ import annotations

import json
from collections import Counter
from pathlib import Path
from typing import Iterator

ROLE_MAP = {
    "developer": "system",
    "system": "system",
    "user": "user",
    "assistant": "assistant",
    "toolResult": "tool",
}


def _text_of(blocks: list) -> str:
    return "".join(
        b.get("text", "")
        for b in blocks
        if isinstance(b, dict) and b.get("type") == "text"
    )


def _normalize_assistant(msg: dict) -> dict:
    text_parts: list[str] = []
    thinking_parts: list[str] = []
    tool_calls: list[dict] = []
    for block in msg.get("content", []):
        if not isinstance(block, dict):
            continue
        btype = block.get("type")
        if btype == "text":
            text_parts.append(block.get("text", ""))
        elif btype == "thinking":
            thinking_parts.append(block.get("thinking", ""))
        elif btype == "toolCall":
            args = block.get("arguments", {})
            if not isinstance(args, str):
                args = json.dumps(args, ensure_ascii=False)
            tool_calls.append(
                {
                    "id": block.get("id", ""),
                    "type": "function",
                    "function": {"name": block.get("name", ""), "arguments": args},
                }
            )
    out: dict = {"role": "assistant", "content": "".join(text_parts)}
    if thinking_parts:
        out["reasoning_content"] = "\n\n".join(thinking_parts)
    if tool_calls:
        out["tool_calls"] = tool_calls
    return out


def parse_trace_file(path: str | Path) -> tuple[list[dict], Counter]:
    """Parse one trace file. Returns (messages, skipped-record counter)."""
    messages: list[dict] = []
    skipped: Counter = Counter()
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
            except json.JSONDecodeError:
                skipped["bad_json"] += 1
                continue
            if rec.get("type") != "message":
                skipped[f"type:{rec.get('type')}"] += 1
                continue
            msg = rec.get("message") or {}
            role = ROLE_MAP.get(msg.get("role"))
            if role is None:
                skipped[f"role:{msg.get('role')}"] += 1
                continue
            if role == "assistant":
                norm = _normalize_assistant(msg)
            elif role == "tool":
                norm = {"role": "tool", "content": _text_of(msg.get("content", []))}
            else:
                norm = {"role": role, "content": _text_of(msg.get("content", []))}
            messages.append(norm)
    return messages, skipped


def iter_turn_examples(messages: list[dict]) -> Iterator[tuple[list[dict], dict]]:
    """Yield one (context, expert_turn) pair per assistant turn in a trace.

    ``context`` is every message before the turn; ``expert_turn`` is the
    expert's assistant message for that turn (the distillation reference).
    Turns with no preceding user message or with empty content are skipped.
    """
    for i, m in enumerate(messages):
        if m["role"] != "assistant":
            continue
        if not (m.get("content") or m.get("tool_calls")):
            continue
        context = messages[:i]
        if not any(c["role"] == "user" for c in context):
            continue
        yield context, m
